"""Biosecurity unit 8: the health-system capacities of the WHO Joint External Evaluation tool and the Biological
Weapons Convention articles that nothing in the framework answered. Sixteen JEE technical areas and six BWC articles.

Policy, preparedness and defence only, as the rest of this framework is: nothing here helps make, enhance, acquire or
deploy a pathogen. The arithmetic is health-system and treaty bookkeeping — coverage, workforce density, surge, decay,
dilution — and is recomputed by the verifier. Where the JEE's own indicator text or capacity levels were not read, the
card asks about the capacity the area names rather than about an indicator score.
"""
from opl_dsl import Q

FILE, FRAMEWORK, PRACTICE = "bs-capacities", "biosecurity", "P2"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
EP, LS, PV, PR = "biosec.epidemiology", "biosec.landscape", "biosec.prevent", "biosec.practice"
J = "who-jee3:"
B = "bwc:"


def facts(name, skill, rows, explain):
    return Q(name, skill, "{{q}}", pace="recall",
             cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


